import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"GSS — Goal-Seeking Strategy","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/GSS.html"}],["meta",{"property":"og:title","content":"GSS — Goal-Seeking Strategy | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/GSS.html"}],["meta",{"name":"twitter:title","content":"GSS — Goal-Seeking Strategy | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"strategies/GSS.md","filePath":"strategies/GSS.md","lastUpdated":1793949528000}`),a={name:`strategies/GSS.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="gss-—-goal-seeking-strategy" tabindex="-1">GSS — Goal-Seeking Strategy <a class="header-anchor" href="#gss-—-goal-seeking-strategy" aria-label="Permalink to “GSS — Goal-Seeking Strategy”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>GSS is a recursive strategy for the <strong>Scoped Range objective</strong>. It plans within the user&#39;s selected start and end dates, maximising the scoped portfolio outcome while accounting for cash-flow events, FD eligibility, transfer fees and liquidity obligations.</p><p>GSS is independent of Greedy, Absolute R and Absolute R+. It consumes the candidate order supplied by FDOptionManager and does not fall back to another strategy when candidates are exhausted; remaining funds stay liquid.</p><p><strong>Implementation:</strong> <code>src/strategies/gss.js</code>.</p><h2 id="planning-model" tabindex="-1">Planning model <a class="header-anchor" href="#planning-model" aria-label="Permalink to “Planning model”">​</a></h2><p>For each candidate account and FD option, GSS evaluates feasible SPLIT and CONSOLIDATE plans. If neither is viable immediately, it projects scheduled inflows, existing FD cash flows/maturities and outflows to find a future affordability date. It recursively plans the waiting period with GSS itself.</p><p>Interim bookings must preserve liquidity required by the parent plan and strict outflow obligations within the selected date range. At each future event boundary, GSS re-evaluates the parent candidate against updated balances and available products.</p><h2 id="candidate-ordering-and-selection" tabindex="-1">Candidate ordering and selection <a class="header-anchor" href="#candidate-ordering-and-selection" aria-label="Permalink to “Candidate ordering and selection”">​</a></h2><p>GSS obtains account-compatible and horizon-compatible FD candidates from FDOptionManager and consumes the manager-provided order. For each candidate, it compares feasible plans using post-AIT interest and actual transfer fees, preserving deterministic manager order as a tie-breaker.</p><p>GSS does not add Goal-specific ranking or search overhead to the scoped planner.</p><h2 id="constraints-and-liquidity" tabindex="-1">Constraints and liquidity <a class="header-anchor" href="#constraints-and-liquidity" aria-label="Permalink to “Constraints and liquidity”">​</a></h2><p>The planner accounts for future scheduled inflows, FD cash flows and outflows when determining whether a booking or transfer is viable.</p><p>A consolidation transfer permanently removes cash from its source account. Source-account liquidity required for obligations later in the requested date range must therefore remain reserved. Split bookings remain in their own accounts and are re-evaluated at maturity.</p><p>Strict outflow constraints are not relaxed to improve investment returns. If the strategy cannot satisfy a strict obligation, the authoritative runtime rejects the result.</p><h2 id="runtime-boundary" tabindex="-1">Runtime boundary <a class="header-anchor" href="#runtime-boundary" aria-label="Permalink to “Runtime boundary”">​</a></h2><p>GSS exposes <code>createSession(context)</code>. Its private recursive planner returns a sequence of decisions; it does not return its hypothetical ledger as the actual simulation result.</p><p><code>SimulationRuntime</code> processes authoritative events, settles outflows, validates transfers and atomically executes selected decisions. Same-date recursive actions are emitted as one atomic batch. <code>SimulationEngine</code> performs the single final consolidation sweep after the scoped session completes.</p><h2 id="optimality-and-limitations" tabindex="-1">Optimality and limitations <a class="header-anchor" href="#optimality-and-limitations" aria-label="Permalink to “Optimality and limitations”">​</a></h2><p>GSS is a recursive heuristic, not an exhaustive search. It follows FDOptionManager&#39;s candidate ordering and evaluates the plans available at each recursive boundary; it does not prove that no better complete sequence exists.</p><p>Candidate exhaustion leaves the remaining funds liquid. GSS does not switch to Greedy, Absolute R or Absolute R+.</p><h2 id="goal-mode-status" tabindex="-1">Goal mode status <a class="header-anchor" href="#goal-mode-status" aria-label="Permalink to “Goal mode status”">​</a></h2><p>GSS is <strong>Scoped Range only</strong>. It is not dual-optimised for earliest Goal achievement. Goal mode remains disabled while a dedicated Absolute R Goal planner is under development.</p><h2 id="diagnostics-and-source-map" tabindex="-1">Diagnostics and source map <a class="header-anchor" href="#diagnostics-and-source-map" aria-label="Permalink to “Diagnostics and source map”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Implementation</th></tr></thead><tbody><tr><td>Recursive planning and decision generation</td><td><code>src/strategies/gss.js</code></td></tr><tr><td>FD option eligibility and candidate ordering</td><td><code>src/fd-options/</code></td></tr><tr><td>Authoritative event processing and decision execution</td><td><code>src/core/simulation-runtime.js</code></td></tr><tr><td>Session driving and final consolidation</td><td><code>src/core/simulation.js</code></td></tr></tbody></table>`,25)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};